-- Booking approval, per requesting role. Both switches are off by default:
-- the feature is opt-in per workspace, so nothing changes for anyone until an
-- owner or administrator turns one on. A workspace that had the single switch
-- on keeps approval for Self service.
ALTER TABLE "BookingSettings" ADD COLUMN "requireApprovalForBase" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "BookingSettings" ADD COLUMN "requireApprovalForSelfService" BOOLEAN NOT NULL DEFAULT false;

UPDATE "BookingSettings"
SET "requireApprovalForSelfService" = "requireBookingApproval";

ALTER TABLE "BookingSettings" DROP COLUMN "requireBookingApproval";

-- Records the approval of a booking reservation request in the activity
-- log. The booking stays RESERVED when approved, so without this event the
-- decision would only live in a free-text note. Nothing in this migration
-- uses the new value.
ALTER TYPE "ActivityAction" ADD VALUE IF NOT EXISTS 'BOOKING_APPROVED';

-- Audits count units of quantity-tracked assets.
-- Both columns stay NULL for individual assets and for every existing row.
ALTER TABLE "AuditAsset" ADD COLUMN "expectedQuantity" INTEGER;
ALTER TABLE "AuditAsset" ADD COLUMN "foundQuantity" INTEGER;

ALTER TABLE "AuditAsset"
  ADD CONSTRAINT "AuditAsset_expectedQuantity_non_negative"
  CHECK ("expectedQuantity" IS NULL OR "expectedQuantity" >= 0);
ALTER TABLE "AuditAsset"
  ADD CONSTRAINT "AuditAsset_foundQuantity_non_negative"
  CHECK ("foundQuantity" IS NULL OR "foundQuantity" >= 0);

-- Booking approval becomes a per-role choice. Base is on by default (a Base
-- member never checks out themself, so the hand-over was always the
-- approval); Self service is off by default. A workspace that had the single
-- switch on keeps approval for Self service too.
ALTER TABLE "BookingSettings" ADD COLUMN "requireApprovalForBase" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "BookingSettings" ADD COLUMN "requireApprovalForSelfService" BOOLEAN NOT NULL DEFAULT false;

UPDATE "BookingSettings"
SET "requireApprovalForSelfService" = "requireBookingApproval";

ALTER TABLE "BookingSettings" DROP COLUMN "requireBookingApproval";

-- A TEXT custom field can be marked as holding a web link. Existing fields
-- become PLAIN, which is how they behave today, so no backfill is needed.

-- CreateEnum
CREATE TYPE "CustomFieldFormat" AS ENUM ('PLAIN', 'LINK');

-- AlterTable
ALTER TABLE "CustomField" ADD COLUMN "format" "CustomFieldFormat" NOT NULL DEFAULT 'PLAIN';

-- Only TEXT fields can be Link fields.
ALTER TABLE "CustomField" ADD CONSTRAINT "CustomField_format_needs_text"
  CHECK ("format" = 'PLAIN' OR "type" = 'TEXT');

-- Phase 3a: Replace the implicit M2M (_AssetToBooking) with the explicit
-- BookingAsset pivot table. Uses a rename strategy — no data is copied.
--
-- The Phase 1 migration created an empty BookingAsset table that coexisted
-- with the implicit M2M. We drop that empty shell and rename the real
-- data-bearing _AssetToBooking table into its place.

-- 1. Drop the empty Phase 1 BookingAsset table (has no data)
DROP TABLE "BookingAsset";

-- 2. Rename the implicit M2M table and its columns
ALTER TABLE "_AssetToBooking" RENAME TO "BookingAsset";
ALTER TABLE "BookingAsset" RENAME COLUMN "A" TO "assetId";
ALTER TABLE "BookingAsset" RENAME COLUMN "B" TO "bookingId";

-- 3. Add quantity column (default 1 for all existing rows)
ALTER TABLE "BookingAsset" ADD COLUMN "quantity" INTEGER NOT NULL DEFAULT 1;

-- 4. Replace composite PK with a text ID primary key
ALTER TABLE "BookingAsset" DROP CONSTRAINT "_AssetToBooking_AB_pkey";
ALTER TABLE "BookingAsset" ADD COLUMN "id" TEXT;
UPDATE "BookingAsset" SET "id" = gen_random_uuid()::text WHERE "id" IS NULL;
ALTER TABLE "BookingAsset" ALTER COLUMN "id" SET NOT NULL;
ALTER TABLE "BookingAsset" ADD CONSTRAINT "BookingAsset_pkey" PRIMARY KEY ("id");

-- 5. Add unique constraint on (bookingId, assetId) to replace the old PK
ALTER TABLE "BookingAsset"
  ADD CONSTRAINT "BookingAsset_bookingId_assetId_key"
  UNIQUE ("bookingId", "assetId");

-- 6. Rename existing B index, add assetId index
ALTER INDEX "_AssetToBooking_B_index" RENAME TO "BookingAsset_bookingId_idx";
CREATE INDEX "BookingAsset_assetId_idx" ON "BookingAsset" ("assetId");

-- 7. Rename foreign key constraints to match Prisma conventions
ALTER TABLE "BookingAsset" RENAME CONSTRAINT "_AssetToBooking_A_fkey" TO "BookingAsset_assetId_fkey";
ALTER TABLE "BookingAsset" RENAME CONSTRAINT "_AssetToBooking_B_fkey" TO "BookingAsset_bookingId_fkey";

-- RLS was already enabled on _AssetToBooking and carries over with the rename.
